# Check if submit exists as any function
import sys
print("Looking for submit functions...")

# Check various locations
for name in dir():
    obj = eval(name)
    if hasattr(obj, '__call__') and 'submit' in name.lower():
        print(f"Found: {name} -> {obj}")

# Also try importing from potential modules
try:
    for mod_name in ['arc', 'continual_arc', 'adversarial_arc']:
        try:
            print(f"Trying to import {mod_name}...")
            __import__(mod_name)
            print(f"  Success: {sys.modules[mod_name]}")
        except ImportError:
            pass
except Exception as e:
    print(f"Error: {e}")
